[K-Doctor 전문과목 알레르기내과 v0.1 적용]

[SPECIALIST_FINDING]
{
  "specialty": "kdoctor-allergy",
  "answer": "만 6세 소아로 이 과목 단독 소견보다 소아 호흡기·알레르기 분과(kdoctor-pediatric-respiratory-allergy)가 우선 적합합니다. 알레르기내과 관점에서는 (1) 야간 기침이 알레르기성 비염·후비루로 설명되는지 여부는 '코 증상-기침의 시간적 연관'과 '입 벌림/코막힘·후비루 신호'로 판별하고, (2) 아토피 평가(피부반응시험/특이 IgE)는 검사 시점보다 '검사 전제(증상-노출 연관이 이미 정리되었는가)'가 먼저이며, (3) 흡입 알레르겐은 집먼지진드기·반려동물·곰팡이 각각의 노출원·노출 시간·증상과의 시간 연관을 항목화해 확인해야 합니다.",
  "red_flag": {
    "present": false,
    "items": []
  },
  "hypotheses": [
    {
      "name": "알레르기성 비염·후비루에 의한 야간 기침(상기도 기침 증후군 범주)",
      "icd10": "J30.1",
      "must_not_miss": false,
      "probability_band": "medium",
      "supports": [
        { "text": "야간 기침 — 누운 자세에서 코 뒤로 흐르는 후비루가 기침을 유발하는 전형적 시간대", "basis": "history" },
        { "text": "운동 후 천명 — 알레르기성 비염이 있는 소아에서 기관지 과민성·운동유발 기관지수축이 동반되는 경우가 흔함", "basis": "guideline" },
        { "text": "아토피 평가 자문 요청 자체가 알레르기 질환 병력 시사", "basis": "history" }
      ],
      "against": [
        { "text": "코막힘·재채기·가려움·맑은 콧물 등 비염 증상이 문진에서 아직 확인되지 않음", "basis": "history" },
        { "text": "천명이 코 증상 없이 운동에만 국한되는지 불명 — 비염만으로 설명 안 되는 운동유발 기관지수축 가능성", "basis": "history" }
      ]
    },
    {
      "name": "운동유발 기관지수축(운동유발 천식 포함)",
      "icd10": "J45.9",
      "must_not_miss": true,
      "probability_band": "medium",
      "supports": [
        { "text": "운동 후 천명 — 운동유발 기관지수축의 핵심 소견", "basis": "history" },
        { "text": "야간 기침 — 천식의 전형적 야간 증상", "basis": "guideline" }
      ],
      "against": [
        { "text": "흡입제 사용·호전 여부, 발작 시 말 이음, 흉부 함몰 등 중증도 지표 미확인", "basis": "history" },
        { "text": "폐기능(스파이로메트리, 기관지유발시험 등) 결과 미제공", "basis": "measurement" }
      ]
    },
    {
      "name": "기타 만성 야간 기침 원인(만성 비염·부비동염, 위식도 역류, 기침 이형 천식)",
      "icd10": "",
      "must_not_miss": true,
      "probability_band": "low",
      "supports": [
        { "text": "소아 만성 야간 기침의 주요 감별군", "basis": "guideline" }
      ],
      "against": [
        { "text": "각 원인 특이 문진(역류 증상·부비동 증상·기침 지속 기간·계절성)이 아직 제공되지 않음", "basis": "history" }
      ]
    }
  ],
  "missing_info": [
    "코 증상(코막힘·맑은 콧물·재채기·코 가려움)과 기침의 시간적 연관 — 같은 날 밤에 코가 심한 날 기침도 심한가? (판별력 가장 큼)"
  ],
  "suggested_tests": [
    {
      "name": "피부반응시험(skin prick test) 또는 특이 IgE — 흡입 알레르겐(집먼지진드기/반려동물/곰팡이) 감작 확인",
      "purpose": "증상-노출 연관이 문진으로 정리된 뒤 감작 여부를 확인·기록하는 목적. 검사 자체가 진단을 대신하지 않음(감작≠증상 원인)",
      "urgency": "routine",
      "basis": "guideline"
    },
    {
      "name": "폐기능 검사(가능 연령 시 스파이로메트리, 필요 시 기관지유발/운동부하 시험)",
      "purpose": "운동 후 천명·야간 기침의 기관지 원인 여부 평가 — 흡입 알레르겐 검사보다 우선순위가 높음",
      "urgency": "routine",
      "basis": "guideline"
    }
  ],
  "suggested_treatments": [
    {
      "kind": "referral",
      "description": "만 6세 소아 — 소아 호흡기·알레르기 분과(kdoctor-pediatric-respiratory-allergy)로 우선 협진. 알레르기내과 단독 평가보다 소아 전용 규칙(연령·체중·검사 적응) 적용이 적절",
      "basis": "guideline"
    },
    {
      "kind": "self_care",
      "description": "흡입 알레르겐 노출 항목화: ① 집먼지진드기 — 침구·매트리스·카펫·봉제인형, 세탁 온도·주기, 침실 습도 ② 반려동물 — 침실 출입·털·침구 접촉, 동물 종 ③ 곰팡이 — 욕실·벽지·에어컨 필터·지하/습한 방, 계절·환기. 각 항목의 '노출 시간'과 '증상 발현 시점'을 일지로 기록",
      "basis": "guideline"
    },
    {
      "kind": "self_care",
      "description": "증상·노출 일지(날짜·코 증상·기침 시간대·운동 여부·노출 알레르겐·약 사용) 작성 후 분과 외래에서 검사 해석 시 근거로 제시",
      "basis": "guideline"
    }
  ],
  "handoff": {
    "better_specialty": "kdoctor-pediatric-respiratory-allergy",
    "reason": "만 6세 소아 — 연령별 검사 적응·해석, 소아 천식/비염 감별, 성장·체중 고려가 필요해 소아 분과 규칙을 우선 적용해야 함(총괄이 통합). 호흡기 중심 증상(천명·야간 기침)이 주이므로 kdoctor-pulmonology 병행 검토도 가능."
  },
  "confidence": {
    "clinical": 3,
    "information": 2
  },
  "warnings": [
    "아나필락시스·후두 부종·중증 천식 발작 등 급성 위험 신호는 본 문진에서 확인되지 않았으나, 향후 '말을 잇기 힘든 숨참, 목 조임, 흡입제로 호전 없음, 얼굴·혀 부기' 발생 시 즉시 119·응급 평가가 우선이다(알레르기 규칙 1·H-2 AL1·AL2·AL6).",
    "특이 IgE·피부반응시험은 '감작'을 보여줄 뿐 '증상 원인'을 확정하지 않는다 — 문진상 노출-증상 연관이 정리된 후 해석해야 하며, 무증상 감작에 대한 광범위 식이·환경 제한은 권하지 않는다(알레르기 규칙 5·7).",
    "검사 시행 시점·중단 약물(항히스타민제 등) 조건은 대면 진료에서 결정 — 본 SP는 세부 수치·기간을 제시하지 않는다(공통 원칙 ④).",
    "용량·투여 방법은 의사·약사 확인."
  ]
}
[/SPECIALIST_FINDING]

자기점검: C1(위험 신호 없음 — 근거 유형 병기) / C2(모든 항목 근거 유형 병기) / C3(확정 표현 없음) / C4(용량 서술 없음) 위반 없음. C5 — 소아·연령 관련 항목은 소아 분과 훅 소관으로 handoff에 명시.
